{
  "document_type": "lease",
  "lessor": "Beijing Shunfeng Runlin Technology and Trade Co., Ltd.",
  "lessee": "Beijing Ninetowns Sky Eco-Agriculture Co., Ltd.",
  "premises_address": "south of Lianying Village, Lianying Village, Quanying Town, Shunyi District, Beijing",
  "area": null,
  "start_date": "2010-03-01",
  "end_date": "2013-02-28",
  "rent": {
    "amount": 550000,
    "currency": "CNY",
    "period": "year"
  },
  "indexation": "none",
  "red_flags": [
    {
      "type": "tenant_break_option",
      "quote": "If Party B fails to perform the lease‘due to its poor performance, it shall notify Party A in Writing one (1) month in advance. After obtaining the consent from Party A, Party B may terminate the Contract without incurring any liability."
    },
    {
      "type": "tenant_break_option",
      "quote": "Party B shall obtain Party A’s prior consent regarding temporarily building fixtures to the site within the term of this Contract, and Party B undertakes that, upon the expiration of this Contract, the fixtures shall be‘owned by Party A and that all temporary buildings shall be vacated."
    },
    {
      "type": "landlord_repairs",
      "quote": "Party A is obligated to maintain the cement road in good condition for passage within the boundary of the premise, and is in charge of the greening work within the boundary of the premise."
    },
    {
      "type": "tenant_break_option",
      "quote": "Party A shall issue its official invoice to Party B prior to March Ist of each year and Party B shall pay the rent for such year."
    },
    {
      "type": "tenant_break_option",
      "quote": "Party A undertakes that during the term of this Contract, Party B’s use of the premise may not be affected by the transfer or mortgage of the land and the constructions on the ground under the lease."
    },
    {
      "type": "tenant_break_option",
      "quote": "Neither Party shall be liable to the other Party due to the occurrenice of any force majeure (earthquake, hurricane, flood, riot, war, etc.) during the term of this Contract. Neither Party shall be liable to the other Party in the event that the Contract is terminated due to governmental expropriation and demolition during the term of this Contract, provided however, that Party A shall notify Party B two (2) months in advance, return the rent for the rest of the year and then terminate the Contract."
    },
    {
      "type": "tenant_break_option",
      "quote": "If Party A’s land and buildings referred to herein are subject to demolition due to governmental expropriation, the compensation for the land use rights and ground constructions received shall belong to Party A. Party A shall notify Party B two (2) months in advance, and shall offer Party B an exeiption of one-month’s rent in addition to returning Party A’s rent for the rest of the year."
    },
    {
      "type": "tenant_break_option",
      "quote": "Both Parties shall fully perform the Contract during the term of this Contract and neither Party may breach the Contract. Both Parties undertake that if either Party breaches the Contract within the term of this Contract, the breaching Party shall pay half of the annual rent as liquidated damages for terminating the Contract."
    },
    {
      "type": "tenant_break_option",
      "quote": "Party B shall pay the annual rent to Party A on time and in full, and in case of any delay in the payment, a penalty shall be paid at the rate of 5%o of the rent that are not paid on time per day. If the delay is over one (I) month, Party A has the right to retrieve the premise and Party B shall be liable for any lossés incurred thereto."
    }
  ]
}
